B.WP=new A.Z(B.t,["Nova City. Uma cidade onde humanos e rob\xf4s vivem juntos, em paz... tudo gra\xe7as \xe0 energia do N\xfacleo Nova.","Nova City. A city where humans and robots live together in peace... all thanks to the energy of the Nova Core.","Nova City. Una ciudad donde humanos y robots viven juntos, en paz... todo gracias a la energ\xeda del N\xfacleo Nova."],t.w)
B.an2=new A.ed(null,B.WP,null)
B.WN=new A.Z(B.t,["Olha s\xf3 esse c\xe9u! Dia perfeito pra treinar. Nada pode estragar isso... n\xe9, Zek?","Look at that sky! A perfect day to train. Nothing can ruin this... right, Zek?","\xa1Mira ese cielo! Un d\xeda perfecto para entrenar. Nada puede arruinarlo... \xbfverdad, Zek?"],t.w)
B.amU=new A.ed("kael",B.WN,"happy")
B.WE=new A.Z(B.t,["Ai, n\xe3o! Por que voc\xea foi falar isso, Kael? Toda vez que algu\xe9m fala isso, d\xe1 tudo errado!","Oh, no! Why did you say that, Kael? Every time someone says that, everything goes wrong!","\xa1Ay, no! \xbfPor qu\xe9 dijiste eso, Kael? \xa1Cada vez que alguien lo dice, todo sale mal!"],t.w)
B.an3=new A.ed("zek",B.WE,"scared")
B.Wu=new A.Z(B.t,["Relaxa, Zek! O que poderia acontecer?","Relax, Zek! What could possibly happen?","\xa1Tranquilo, Zek! \xbfQu\xe9 podr\xeda pasar?"],t.w)
B.amS=new A.ed("kael",B.Wu,"happy")
B.Ty=s([B.an2,B.amU,B.an3,B.amS],t.tG)
B.an9=new A.lR("intro_1.jpg",1.05,1.18,B.dU,B.dT,B.Ty)
B.X8=new A.Z(B.t,["Gente... olhem pra cima! O sol... est\xe1 sumindo!","Guys... look up! The sun... is disappearing!","Chicos... \xa1miren arriba! El sol... \xa1est\xe1 desapareciendo!"],t.w)
B.amX=new A.ed("luna",B.X8,"scared")
B.X1=new A.Z(B.t,["Que coisa gigante \xe9 aquela?! Parece um castelo voando!","What is that giant thing?! It looks like a flying castle!","\xbf\xa1Qu\xe9 es esa cosa gigante!? \xa1Parece un castillo volando!"],t.w)
B.amY=new A.ed("mira",B.X1,"shocked")
B.WC=new A.Z(B.t,["Durante o eclipse, uma fortaleza sombria surgiu no c\xe9u: a Cidadela Eclipse.","During the eclipse, a dark fortress rose in the sky: the Eclipse Citadel.","Durante el eclipse, una fortaleza oscura apareci\xf3 en el cielo: la Ciudadela Eclipse."],t.w)
B.an1=new A.ed(null,B.WC,null)
B.R2=s([B.amX,B.amY,B.an1],t.tG)
B.an6=new A.lR("intro_2.jpg",1.05,1.18,B.bm,B.b2,B.R2)
B.WO=new A.Z(B.t,["Ha ha ha ha! Povo de Nova City... a energia do N\xfacleo Nova agora pertence a MIM!","Ha ha ha ha! People of Nova City... the energy of the Nova Core now belongs to ME!","\xa1Ja ja ja ja! Pueblo de Nova City... \xa1la energ\xeda del N\xfacleo Nova ahora me pertenece a M\xcd!"],t.w)
B.amP=new A.ed("emperor",B.WO,"laugh")
B.WQ=new A.Z(B.t,["Meus nove chefes v\xe3o guard\xe1-la pelo mundo inteiro. E voc\xeas, heroizinhos... v\xe3o passar uma temporada nas minhas c\xe1psulas!","My nine bosses will guard it all over the world. And you, little heroes... will spend some time in my capsules!","Mis nueve jefes la guardar\xe1n por todo el mundo. Y ustedes, hero\xedtos... \xa1pasar\xe1n una temporada en mis c\xe1psulas!"],t.w)
B.amQ=new A.ed("emperor",B.WQ,null)
B.Ww=new A.Z(B.t,["Isso \xe9 o que voc\xea pensa!","That's what you think!","\xa1Eso es lo que t\xfa crees!"],t.w)
B.amT=new A.ed("kael",B.Ww,"angry")
B.Rj=s([B.amP,B.amQ,B.amT],t.tG)
B.an7=new A.lR("intro_3.jpg",1.25,1.05,B.k,B.k,B.Rj)
B.Wy=new A.Z(B.t,["Num instante, Luna, Mira, Zek e Nex foram levados... e trancados em c\xe1psulas, escondidas nas terras dos nove chefes.","In an instant, Luna, Mira, Zek and Nex were taken... and locked in capsules, hidden in the lands of the nine bosses.","En un instante, Luna, Mira, Zek y Nex fueron llevados... y encerrados en c\xe1psulas, escondidas en las tierras de los nueve jefes."],t.w)
B.an0=new A.ed(null,B.Wy,null)
B.Xd=new A.Z(B.t,["N\xc3\xc3\xc3O! Pessoal!! Aguentem firme... eu juro que vou achar cada um de voc\xeas!","NOOO! Guys!! Hang in there... I swear I'll find every one of you!","\xa1NOOO! \xa1\xa1Chicos!! Aguanten... \xa1les juro que los voy a encontrar a todos!"],t.w)
B.amW=new A.ed("kael",B.Xd,"desperate")
B.SO=s([B.an0,B.amW],t.tG)
B.an4=new A.lR("intro_4.jpg",1.05,1.18,B.dT,B.dU,B.SO)
B.Wn=new A.Z(B.t,["Kael... est\xe1 me ouvindo? Estou falando com voc\xea pela energia do vazio.","Kael... can you hear me? I'm talking to you through the void energy.","Kael... \xbfme oyes? Te hablo a trav\xe9s de la energ\xeda del vac\xedo."],t.w)
B.amZ=new A.ed("nex",B.Wn,null)
B.X5=new A.Z(B.t,["As c\xe1psulas est\xe3o bem escondidas. Procure em cada canto... e cuidado com os chefes.","The capsules are well hidden. Search every corner... and watch out for the bosses.","Las c\xe1psulas est\xe1n bien escondidas. Busca en cada rinc\xf3n... y cuidado con los jefes."],t.w)
